"""Migrated VAL-01 opportunity validation rules."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(row: dict | None, field: str) -> Any:
    if row is None:
        return ""
    value = row.get(field, "")
    return "" if value is None else value


def _text(row: dict | None, field: str) -> str:
    value = _value(row, field)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _date_greater_or_equal(left: Any, right: Any) -> bool:
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image in legacy rule-file order."""
    errors: list[dict] = []

    def add(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    amt = _number(_nvl(_value(record, "AMT"), 0))
    stat_cd = _text(record, "STAT_CD")
    lost_rsn = _text(record, "LOST_RSN")
    close_dt = _text(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not amt >= Decimal(0):
            add("E3001", "Amount negative")

        # OPP-002
        if not (not (stat_cd == "W" and amt == Decimal(0))):
            add("E3002", "Won opportunity requires amount")

        # OPP-003
        if not (not (stat_cd == "L" and lost_rsn == "")):
            add("E3003", "Lost reason required")

        # OPP-004
        if not (not (stat_cd == "W" and close_dt == "00000000")):
            add("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        # OLD references resolve to empty string for INSERT; this rule only runs on UPDATE.
        old_stat_cd = _text(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            add("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        stage_matches_status = (
            (stat_cd == "P" and stage_pct == Decimal(10))
            or (stat_cd == "Q" and stage_pct == Decimal(25))
            or (stat_cd == "N" and stage_pct == Decimal(60))
            or (stat_cd == "W" and stage_pct == Decimal(100))
            or (stat_cd == "L" and stage_pct == Decimal(0))
        )
        if not stage_matches_status:
            add("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        # OPP-007
        if not (
            close_dt == "00000000"
            or _date_greater_or_equal(close_dt, today)
        ):
            add("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
